from pathlib import Path
p=Path('app.js');s=p.read_text()
s=s.replace("recognition:null};", "recognition:null,readingStage:0,readingWordIndex:0};")
s=s.replace("function practiceNow(){state.tab='speak';render()}","function practiceNow(){state.tab='speak';state.readingWordIndex=state.index;state.readingStage=0;render()}")
start=s.index('function normalize(s)')
end=s.index('function progress()',start)
new=r'''function normalize(s){return String(s).toLowerCase().replace(/[^a-z\s']/g,' ').replace(/\s+/g,' ').trim()}
const STAGES=[{title:'1 · Một từ',hint:'Đọc rõ một từ'},{title:'2 · Cụm từ ngắn',hint:'Đọc một cụm từ'},{title:'3 · Một câu',hint:'Đọc một câu hoàn chỉnh'},{title:'4 · Ba câu',hint:'Đọc ba câu liên tiếp'},{title:'5 · Đoạn năm câu',hint:'Đọc đoạn văn gồm năm câu'}];
function targetWord(){return words()[Math.min(state.readingWordIndex,words().length-1)]}
function readingTexts(w){let example=(w.example||`I use the word ${w.word}.`).trim();if(!/[.!?]$/.test(example))example+='.';let phrase=w.word.includes(' ')?w.word:`the word ${w.word}`;let a=state.level==='A1–A2'?['I learn new English words every day.','I listen carefully and speak slowly.','I practice with my friends.','I feel happy when I improve.']:state.level==='B1–B2'?['This vocabulary is useful in everyday communication.','I try to understand its meaning in context.','Regular practice helps me become more confident.','I can use what I learn in real conversations.']:['Understanding vocabulary in context improves communication.','I consider the subtle meaning behind each expression.','Consistent practice strengthens both accuracy and fluency.','Applying new language in authentic situations is essential.'];return [w.word,phrase,example,[example,...a.slice(0,2)].join(' '),[example,...a].join(' ')]}
function changeStage(i){state.readingStage=Math.max(0,Math.min(4,i));render()}
function readingMove(d){state.readingWordIndex=(state.readingWordIndex+d+words().length)%words().length;render()}
function sayReading(){speakText(readingTexts(targetWord())[state.readingStage])}
function tokenAlignment(target,heard){const a=normalize(target).split(' ').filter(Boolean),b=normalize(heard).split(' ').filter(Boolean);let dp=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)dp[i][j]=a[i-1]===b[j-1]?dp[i-1][j-1]+1:Math.max(dp[i-1][j],dp[i][j-1]);let flags=Array(a.length).fill(false),i=a.length,j=b.length;while(i>0&&j>0){if(a[i-1]===b[j-1]){flags[i-1]=true;i--;j--}else if(dp[i-1][j]>=dp[i][j-1])i--;else j--}return {score:Math.round(100*flags.filter(Boolean).length/Math.max(a.length,b.length,1)),tokens:a,flags}}
function scoreStyle(score){if(score>=90)return {label:'Xuất sắc',color:'#15803d',bg:'#dcfce7'};if(score>=70)return {label:'Tốt',color:'#3f8b34',bg:'#ecfccb'};if(score>=50)return {label:'Cần luyện thêm',color:'#a16207',bg:'#fef3c7'};if(score>=30)return {label:'Cần cải thiện',color:'#c2410c',bg:'#ffedd5'};return {label:'Thử lại nhé',color:'#dc2626',bg:'#fee2e2'}}
function scoreReading(heard){let w=targetWord(),target=readingTexts(w)[state.readingStage],result=tokenAlignment(target,heard),sty=scoreStyle(result.score);saved.speaking=saved.speaking||[];saved.speaking.unshift({word:w.word,level:state.level,topic:state.topic,stage:state.readingStage+1,score:result.score,date:new Date().toLocaleDateString('vi-VN')});saved.speaking=saved.speaking.slice(0,100);persist();let colored=result.tokens.map((t,i)=>`<span class="token ${result.flags[i]?'token-ok':'token-bad'}">${escapeHTML(t)}</span>`).join(' ');let box=$('#feedback');if(!box)return;box.innerHTML=`<div class="score-result"><div class="score-circle" style="--score-color:${sty.color};--score-bg:${sty.bg}">${result.score}%</div><h3 style="color:${sty.color}">${sty.label}</h3><div class="score-meter"><div style="width:${result.score}%;background:${sty.color}"></div></div><p class="muted">Độ khớp từ được nhận dạng</p><div class="marked-reading">${colored}</div><p><b>Hệ thống nghe được:</b> ${escapeHTML(heard||'(không có lời nói được nhận dạng)')}</p><p class="muted">🟢 Xanh: từ khớp · 🔴 Đỏ: từ bị thiếu hoặc khác. Đọc lại các từ màu đỏ để cải thiện.</p><div class="actions"><button class="secondary" onclick="sayReading()">🔊 Nghe lại</button><button class="primary" onclick="listen()">🎙️ Thử lại</button>${state.readingStage<4?'<button class="ghost" onclick="changeStage(state.readingStage+1)">Mức tiếp →</button>':''}</div><small class="disclaimer">Điểm này đo mức khớp văn bản nhận dạng, không đo chính xác từng âm, trọng âm hay ngữ điệu; không phải điểm IELTS hoặc AI đánh giá phát âm chuyên sâu.</small></div>`}
function scoreTyped(){scoreReading($('#manual-transcript')?.value||'')}
function listen(){let Rec=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Rec){$('#feedback').innerHTML='<div class="notice warning">Thiết bị/trình duyệt không hỗ trợ nhận dạng giọng nói. Bạn có thể nghe mẫu và dùng ô nhập văn bản để thử cách chấm.</div>';return}try{let r=new Rec();r.lang='en-US';r.interimResults=false;r.maxAlternatives=1;state.recognition=r;$('#feedback').innerHTML='<div class="notice">🎙️ Đang nghe... Hãy đọc toàn bộ nội dung. Cho phép quyền micro khi được hỏi.</div>';r.onresult=e=>scoreReading(e.results[0][0].transcript);r.onerror=e=>{let f=$('#feedback');if(f)f.innerHTML='<div class="notice warning">Không thể nhận dạng: '+escapeHTML(e.error)+'. Kiểm tra quyền micro, Safari và kết nối mạng.</div>'};r.start()}catch(e){$('#feedback').innerHTML='<div class="notice warning">Không thể mở micro trên trình duyệt này.</div>'}}
function speak(){let w=targetWord();if(!w){nav('home');return}let target=readingTexts(w)[state.readingStage];shell(`<div class="panel"><div class="label">🎙️ Luyện đọc theo cấp độ · ${escapeHTML(state.level)}</div><h2>5 mức: từ ngắn → đoạn 5 câu</h2><div class="stage-row">${STAGES.map((v,i)=>`<button class="stage ${state.readingStage===i?'stage-active':''}" onclick="changeStage(${i})">${i+1}</button>`).join('')}</div><div class="label">${STAGES[state.readingStage].title}</div><p class="muted">${STAGES[state.readingStage].hint} · Từ trọng tâm: <b>${escapeHTML(w.word)}</b></p><div class="reading-passage">${escapeHTML(target)}</div><div class="actions">${button('🔊 Nghe mẫu','sayReading()')}${button('🎙️ Đọc và chấm','listen()','primary')}</div><div id="feedback" class="muted" style="margin-top:16px">Nhấn “Nghe mẫu”, sau đó “Đọc và chấm”. Kết quả hiển thị bằng màu sắc theo mức 0–100%.</div><details class="manual"><summary>Thử chấm bằng văn bản (khi micro không hỗ trợ)</summary><textarea id="manual-transcript" rows="3" placeholder="Nhập những từ hệ thống nhận dạng được..."></textarea><button class="secondary" onclick="scoreTyped()">Chấm văn bản</button></details><div class="actions" style="margin-top:20px">${button('← Từ trước','readingMove(-1)','ghost')}${button('Từ tiếp →','readingMove(1)','ghost')}</div><p class="muted">Nhận dạng giọng nói trên iPhone có thể cần internet và quyền micro. Chấm theo độ khớp từ, không phải chấm chất lượng phát âm bằng AI.</p></div>`)}
'''
s=s[:start]+new+s[end:]
p.write_text(s)
p=Path('style.css');p.write_text(p.read_text()+'''\n.stage-row{display:flex;gap:8px;margin:16px 0}.stage{flex:1;border:1px solid #c9d8e8;border-radius:12px;background:#eef4fb;color:#284a70;padding:12px 0;font-weight:800}.stage-active{background:#154579;color:#fff}.reading-passage{background:#f0f6ff;border:1px solid #d8e7f8;border-radius:17px;padding:23px 16px;font-size:19px;line-height:1.8;text-align:left;margin:15px 0 20px}.score-result{text-align:center;padding:16px 10px;border-radius:18px;background:#f8fbff}.score-circle{height:118px;width:118px;border-radius:50%;border:8px solid var(--score-color);background:var(--score-bg);display:grid;place-items:center;margin:0 auto 10px;font-size:34px;font-weight:900;color:var(--score-color)}.score-meter{height:12px;background:#e4eaf2;border-radius:20px;overflow:hidden;margin:12px 0}.score-meter div{height:100%;transition:width .4s}.marked-reading{line-height:2.2;font-size:17px;text-align:left;margin:18px 0;padding:12px;border-radius:12px;background:#fff}.token{display:inline-block;padding:0 5px;margin:2px 0;border-radius:5px}.token-ok{background:#dcfce7;color:#166534}.token-bad{background:#fee2e2;color:#b91c1c;text-decoration:underline}.disclaimer{display:block;color:#6b7d92;margin-top:14px;line-height:1.5}.manual{margin-top:20px;padding:12px;border:1px solid #dbe5f0;border-radius:12px}.manual summary{cursor:pointer;font-size:13px;color:#466584}.manual textarea{width:100%;margin:12px 0;padding:10px;border:1px solid #cad8e8;border-radius:10px;font:inherit}\n''')
p=Path('sw.js');p.write_text(p.read_text().replace('vocab-trainer-2026-v4','vocab-trainer-2026-v5'))
p=Path('README.md');p.write_text(p.read_text()+'''\n\n## Luyện đọc 5 cấp độ (bản nâng cấp)\n- 1 từ → cụm ngắn → 1 câu → 3 câu → đoạn 5 câu.\n- Điểm khớp nhận dạng 0–100%: xanh lá 90–100, xanh nhạt 70–89, vàng 50–69, cam 30–49, đỏ 0–29.\n- Từng từ được đánh dấu xanh (khớp) hoặc đỏ (chưa khớp).\n- Có thể nghe mẫu, đọc lại, chuyển cấp độ và lưu lịch sử.\n- Đây là **độ khớp bản ghi nhận dạng giọng nói**, không phải điểm phát âm AI chuyên sâu. GitHub Pages tĩnh không có backend để bảo vệ khóa API chấm phát âm.\n''')
